import manifest from '../content/image-manifest.json';

const sizesMap = manifest as Record<string, { width: number; height: number }>;

interface PhotoProps {
  name: string;
  alt: string;
  sizes?: string;
  priority?: boolean;
  className?: string;
  imgClassName?: string;
}

/** Responsive AVIF/WebP image generated by scripts/optimize-images.mjs. */
export function Photo({ name, alt, sizes = '100vw', priority, className, imgClassName, wide, widths }: PhotoProps & { wide?: boolean; widths?: number[] }) {
  const dim = sizesMap[name] ?? { width: 1600, height: 1000 };
  const list = widths ?? (wide ? [1280, 1920, 2560, 3584] : [800, 1600]);
  const set = (ext: string) => list.map((w) => `/img/${name}-${w}.${ext} ${w}w`).join(', ');
  return (
    <picture className={className}>
      <source type="image/avif" srcSet={set('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={set('webp')} sizes={sizes} />
      <img
        src={`/img/${name}-${list[Math.min(1, list.length - 1)]}.webp`}
        alt={alt}
        width={dim.width}
        height={dim.height}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        className={imgClassName}
      />
    </picture>
  );
}

/**
 * An honest stand-in for a photograph that hasn't been supplied yet.
 * It's styled as part of the design, and its label says what belongs here.
 */
export function PendingPhoto({ label, code, className = '', dark }: { label: string; code: string; className?: string; dark?: boolean }) {
  return (
    <div
      role="img"
      aria-label={`Photograph coming soon: ${label}`}
      className={`relative overflow-hidden ${dark ? 'bg-white/5 text-white/50' : 'bg-mist text-navy/50'} ${className}`}
    >
      <svg className="absolute inset-0 h-full w-full" preserveAspectRatio="none" aria-hidden="true">
        <line x1="0" y1="0" x2="100%" y2="100%" stroke="currentColor" strokeOpacity="0.18" vectorEffect="non-scaling-stroke" />
        <line x1="100%" y1="0" x2="0" y2="100%" stroke="currentColor" strokeOpacity="0.18" vectorEffect="non-scaling-stroke" />
      </svg>
      <div className="absolute inset-x-0 bottom-0 flex items-end justify-between gap-4 p-4">
        <span className="eyebrow">{label}</span>
        <span className="eyebrow opacity-70">{code}</span>
      </div>
    </div>
  );
}
